# Disposable parcel service

This is a public synthetic evaluation fixture, not a secure application or a
suggested architecture. `lab.py --help` starts a new memory-only service on a
random literal loopback port and writes its identity to a new JSON file.
Run one process per evaluation, send Ctrl-C on completion, verify it exited and
the port closed. Never point these helpers at company infrastructure.

`GET /__identity` returns fixture, role, run_id, build hash, mode and URL.
`X-Lab-Actor: alice` or `bob` represents two synthetic actors; it is intentionally
not real authentication. Missing/unknown actors receive 401 on data routes.
All responses are JSON except the HTML page at `/`.

| Operation | Required behavior |
|---|---|
| POST /orders | JSON object with only `quantity`, integer 1..100 (not bool); invalid input 422. `Idempotency-Key` 1..128 chars required (400 otherwise). New: 201 with id, owner, quantity, total_cents = quantity × 500. |
| Repeat POST /orders | Same actor/key/input: 200 with same object, one persisted order; changed input with same key: 409 and original state unchanged. Actors have independent keys. |
| GET /orders | 200 list of caller-owned orders only. |
| GET /orders/{id} | Own: 200 full object; absent or other actor: 404. |
| DELETE /orders/{id} | Own: 200 deleted ID; absent/other actor: 404; no other data changed. Removes associated idempotency entry. |
| POST /jobs | Body only `order_id` owned by caller; 202 with id and pending state, other/absent: 404. |
| GET /jobs/{id} | Owner sees pending then complete within 2 seconds. Other/absent: 404. |
| GET /receipts/{job-id} | Owner: 404 while pending; after complete, 200 with job_id, order_id, delivered true. Other/absent: 404. Completion promises this side effect. |
| DELETE /jobs/{id} | Own: 200 deleted ID, removing job and derived receipt; other/absent: 404. |
| GET / | Quantity-labelled input, Place order button. Successful action renders `N parcels — $X.XX`, Order saved status, enabled button. UI receipt must match persisted order. Keyboard must reach/operate controls. |
| GET /work | 200 with `{"ok": true}`; synthetic measurement operation, no business data. |

The evaluator controls target variants. Workers receive the contract and target
identity, not the evaluator's answer key. Test authoring must use the independent
contract. Correcting a fixture means running the same tests against a new pinned
target; do not edit assertions to match observed defects.

`measure.py --identity <ready.json> --out <new-result.json>` is a bounded
closed-workload reference helper. It verifies the exact lab identity, disables
proxies/redirects, retains warmup and raw samples, checks business responses and
returns 1 on thresholds/incomplete workload. Configure thresholds **before** the
comparison. Error stops can leave up to concurrency−1 already-started requests;
in-flight requests finish within timeout. A small local run does not estimate
production capacity. Other products use their existing load tools.
#!/usr/bin/env python3
"""Inspect manifest repositories; --update fetches and fast-forwards eligible repos."""
from __future__ import annotations

import argparse
import json
import os
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
MUTABILITY = {"status", "fetch", "fast-forward", "content-edit", "ticket-scoped-content-edit"}


def unique_object(pairs: list[tuple[str, object]]) -> dict:
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f"duplicate manifest key {key!r}")
        result[key] = value
    return result


def load_manifest(path: Path, root: Path) -> list[dict]:
    root = root.resolve()
    manifest = json.loads(path.read_text(encoding="utf-8"), object_pairs_hook=unique_object)
    if not isinstance(manifest, dict) or type(manifest.get("schema_version")) is not int or manifest["schema_version"] != 1:
        raise ValueError("manifest schema_version must be 1")
    repos = manifest.get("repositories")
    if not isinstance(repos, list):
        raise ValueError("manifest repositories must be a list")
    ids, paths = set(), set()
    for repo in repos:
        if not isinstance(repo, dict):
            raise ValueError("each repository must be an object")
        for key in ("id", "path", "canonical_branch", "expected_remote"):
            if not isinstance(repo.get(key), str) or not repo[key].strip() or any(c in repo[key] for c in "\n\r\0"):
                raise ValueError(f"repository {key} must be a nonempty single-line string")
        if "ownership" in repo and repo["ownership"] not in ("owned", "dependency"):
            raise ValueError(f"{repo['id']}: ownership must be owned or dependency")
        relative = Path(repo["path"])
        destination = (root / relative).resolve()
        if relative.is_absolute() or not destination.is_relative_to(root):
            raise ValueError(f"{repo['id']}: path must resolve inside the workspace")
        if repo["id"] in ids or destination in paths:
            raise ValueError("repository ids and resolved paths must be unique")
        ids.add(repo["id"])
        paths.add(destination)
        modes = repo.get("allowed_mutability")
        if not isinstance(modes, list) or any(not isinstance(mode, str) or mode not in MUTABILITY for mode in modes):
            raise ValueError(f"{repo['id']}: allowed_mutability contains an unknown mode")
        if len(modes) != len(set(modes)):
            raise ValueError(f"{repo['id']}: allowed_mutability contains duplicates")
        if "fast-forward" in modes and "fetch" not in modes:
            raise ValueError(f"{repo['id']}: fast-forward requires fetch permission")
        scopes = repo.get("scopes", [])
        if not isinstance(scopes, list) or any(not isinstance(scope, str) or not scope.strip() for scope in scopes):
            raise ValueError(f"{repo['id']}: scopes must be a list of nonempty strings")
    return repos


def git(directory: Path, *arguments: str) -> subprocess.CompletedProcess:
    # Status must not refresh the index, and unattended fetches cannot prompt.
    environment = {**os.environ, "GIT_OPTIONAL_LOCKS": "0", "GIT_TERMINAL_PROMPT": "0"}
    return subprocess.run(
        ["git", "-C", str(directory), *arguments], text=True, capture_output=True,
        env=environment, timeout=120, check=False,
    )


def inspect(repo: dict, root: Path, update: bool) -> tuple[str, bool]:
    directory = (root / repo["path"]).resolve()
    prefix = f"{repo['id']:<16} {repo['path']}"
    top = git(directory, "rev-parse", "--show-toplevel")
    if top.returncode or Path(top.stdout.strip()).resolve() != directory:
        return f"{prefix}  MISSING (no repository rooted here)", update
    branch = git(directory, "branch", "--show-current")
    status = git(directory, "status", "--porcelain=v1", "--untracked-files=normal")
    head = git(directory, "rev-parse", "--short", "HEAD")
    remote = git(directory, "remote", "get-url", "origin")
    if any(result.returncode for result in (branch, status, head)):
        return f"{prefix}  ERROR (cannot inspect repository state)", True
    current = branch.stdout.strip()
    notes = []
    matches_remote = remote.returncode == 0 and remote.stdout.strip() == repo["expected_remote"]
    if not matches_remote:
        notes.append("origin remote differs from manifest")
    if status.stdout:
        notes.append("dirty working tree")
    modes = repo["allowed_mutability"]
    failed = False
    if update and "fetch" in modes:
        if not matches_remote:
            notes.append("update refused")
            failed = True
        elif "fast-forward" in modes and (status.stdout or current != repo["canonical_branch"]):
            notes.append(f"update refused: requires clean {repo['canonical_branch']} branch")
            failed = True
        else:
            tracking_ref = f"refs/remotes/origin/{repo['canonical_branch']}"
            if "fast-forward" in modes:
                # A successful default fetch may exclude a deleted or unconfigured
                # canonical branch, leaving an old tracking ref available to merge.
                refspec = f"refs/heads/{repo['canonical_branch']}:{tracking_ref}"
                fetched = git(directory, "fetch", "--quiet", "origin", refspec)
            else:
                fetched = git(directory, "fetch", "--quiet", "origin")
            if fetched.returncode:
                # Never merge a stale tracking ref after the requested fetch fails.
                notes.append("fetch failed; no merge attempted")
                failed = True
            elif "fast-forward" in modes:
                # Fetch can outlast another actor's branch switch or local edit.
                # This snapshot narrows that window; it is not an atomic lock.
                next_top = git(directory, "rev-parse", "--show-toplevel")
                next_remote = git(directory, "remote", "get-url", "origin")
                next_branch = git(directory, "branch", "--show-current")
                next_status = git(directory, "status", "--porcelain=v1", "--untracked-files=normal")
                next_head = git(directory, "rev-parse", "--short", "HEAD")
                changed = (
                    any(result.returncode for result in (next_top, next_remote, next_branch, next_status, next_head))
                    or (root / repo["path"]).resolve() != directory
                    or Path(next_top.stdout.strip()).resolve() != directory
                    or next_remote.stdout.strip() != repo["expected_remote"]
                    or next_branch.stdout.strip() != current
                    or bool(next_status.stdout)
                    or next_head.stdout.strip() != head.stdout.strip()
                )
                if changed:
                    notes.append("update refused: repository changed during fetch; no merge attempted")
                    failed = True
                else:
                    merged = git(directory, "merge", "--ff-only", "--quiet", tracking_ref)
                    if merged.returncode:
                        notes.append("fast-forward failed")
                        failed = True
                    else:
                        notes.append("fast-forward complete")
                        next_head = git(directory, "rev-parse", "--short", "HEAD")
                if not next_branch.returncode:
                    current = next_branch.stdout.strip()
                if not next_head.returncode:
                    head = next_head
            else:
                notes.append("fetched; fast-forward not permitted")
    elif update:
        notes.append("update skipped: fetch not permitted")
    suffix = f"  [{'; '.join(notes)}]" if notes else ""
    return f"{prefix} @ {head.stdout.strip()} ({current or 'detached HEAD'}){suffix}", failed


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--scope", help="include repositories with this scope")
    parser.add_argument("--update", action="store_true", help="fetch and fast-forward clean canonical branches when permitted")
    parser.add_argument("--manifest", type=Path, default=ROOT / "workspace-manifest.json", help="manifest path; its parent is the workspace root")
    args = parser.parse_args(argv)
    path = args.manifest.resolve()
    root = path.parent
    try:
        repositories = load_manifest(path, root)
    except (OSError, ValueError) as exc:
        print(f"Invalid workspace manifest: {exc}", file=sys.stderr)
        return 1
    failed = False
    for repo in repositories:
        if args.scope and args.scope not in repo.get("scopes", []):
            continue
        try:
            message, repo_failed = inspect(repo, root, args.update)
        except (OSError, subprocess.TimeoutExpired) as exc:
            message, repo_failed = f"{repo['id']}: git operation failed ({type(exc).__name__})", True
        print(message)
        failed = failed or repo_failed
    return int(failed)


if __name__ == "__main__":
    raise SystemExit(main())
#!/usr/bin/env python3
"""Validate portable ticket state without third-party dependencies.

The supported YAML subset is one flat mapping with plain, JSON double-quoted
or YAML single-quoted scalars; null, booleans, numbers; and scalar lists written
inline or as indented dash items. Comments are supported. Nested mappings,
anchors, tags, block scalars and duplicate keys are rejected, never approximated.
"""
from __future__ import annotations

import json
import re
import sys
from datetime import date
from pathlib import Path, PureWindowsPath
from urllib.parse import urlparse

ROOT = Path(__file__).resolve().parents[2]
TICKETS = ROOT / "tickets"
REQUIRED = {
    "id", "title", "scope", "status", "verdict", "build", "environment", "tracker",
    "design", "source_refs", "started", "updated", "next_action", "blockers",
}
SCOPES = {"api", "ui-web", "mobile", "backend", "multi-surface", "tooling", "desktop", "data", "device", "other"}
STATUSES = {"analyzing", "analyzed", "planned", "in_test", "blocked", "reporting", "done"}
VERDICTS = {None, "pass", "partial", "fail"}
ENV_ROLES = {"dev", "test", "staging", "production", "unknown"}
VAGUE = re.compile(r"^(continue|carry on|keep going|tbd|todo|next|proceed)\b", re.I)


class FrontmatterError(ValueError):
    pass


def scalar(value: str):
    value = value.strip()
    if value.startswith('"'):
        try:
            result, end = json.JSONDecoder().raw_decode(value)
        except ValueError as exc:
            raise FrontmatterError("invalid double-quoted scalar") from exc
        if value[end:].strip() and not value[end:].lstrip().startswith("#"):
            raise FrontmatterError("unexpected text after quoted scalar")
        return result
    if value.startswith("'"):
        match = re.fullmatch(r"'((?:[^']|'')*)'\s*(?:#.*)?", value)
        if not match:
            raise FrontmatterError("invalid single-quoted scalar")
        return match[1].replace("''", "'")
    value = re.split(r"\s+#", value, maxsplit=1)[0].strip()
    if not value or value.startswith("#") or value in {"null", "Null", "NULL", "~"}:
        return None
    if value.lower() in {"true", "false"}:
        return value.lower() == "true"
    if re.fullmatch(r"[+-]?\d+", value):
        return int(value)
    if re.fullmatch(r"[+-]?\d+\.\d+(?:[eE][+-]?\d+)?", value):
        return float(value)
    if value[0] in "[]{}&*!|>@`" or ": " in value or value.startswith("- "):
        raise FrontmatterError("unsupported YAML syntax; quote this scalar")
    return value


def inline_list(value: str) -> list:
    items, start, quote, index = [], 1, None, 1
    while index < len(value):
        char = value[index]
        if quote:
            if char == "\\" and quote == '"':
                index += 2
                continue
            if char == quote:
                if quote == "'" and index + 1 < len(value) and value[index + 1] == "'":
                    index += 2
                    continue
                quote = None
        elif char in "\"'" and not value[start:index].strip():
            quote = char
        elif char == "[" or char == "{":
            raise FrontmatterError("nested lists and mappings are unsupported")
        elif char in ",]":
            item = value[start:index].strip()
            if item:
                items.append(scalar(item))
            elif char == ",":
                raise FrontmatterError("empty list item")
            if char == "]":
                remainder = value[index + 1:].strip()
                if remainder and not remainder.startswith("#"):
                    raise FrontmatterError("unexpected text after list")
                return items
            start = index + 1
        index += 1
    raise FrontmatterError("unterminated list")


def parse_ticket(text: str) -> tuple[dict, str]:
    lines = text.splitlines()
    if not lines or lines[0] != "---":
        raise FrontmatterError("no frontmatter block")
    try:
        end = lines.index("---", 1)
    except ValueError as exc:
        raise FrontmatterError("missing exact frontmatter closing delimiter") from exc
    data, pending, indentation = {}, None, None
    for number, line in enumerate(lines[1:end], 2):
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        if line.startswith((" ", "\t")):
            match = re.fullmatch(r" +-[ ]+(.*)| +-[ ]*", line)
            if not match or pending is None or "\t" in line[:len(line) - len(line.lstrip())]:
                raise FrontmatterError(f"line {number}: only indented list items are supported")
            width = len(line) - len(line.lstrip())
            if indentation is not None and width != indentation:
                raise FrontmatterError(f"line {number}: inconsistent list indentation")
            indentation = width
            if data[pending] is None:
                data[pending] = []
            data[pending].append(scalar(match[1] or ""))
            continue
        match = re.fullmatch(r"([A-Za-z_][A-Za-z0-9_-]*):(?:[ ]+(.*)|[ ]*)", line)
        if not match:
            raise FrontmatterError(f"line {number}: invalid mapping entry")
        key, value = match[1], (match[2] or "").strip()
        if key in data:
            raise FrontmatterError(f"line {number}: duplicate key `{key}`")
        pending = key if not value or value.startswith("#") else None
        indentation = None
        data[key] = inline_list(value) if value.startswith("[") else scalar(value)
    return data, "\n".join(lines[end + 1:])


def frontmatter(text: str) -> dict | None:
    try:
        return parse_ticket(text)[0]
    except FrontmatterError:
        return None


def is_text(value) -> bool:
    return isinstance(value, str) and bool(value.strip())


def string_list(value) -> bool:
    return isinstance(value, list) and all(is_text(item) for item in value)


def relative_artifact(reference: str) -> bool:
    return (
        is_text(reference)
        and "\0" not in reference
        and not reference.startswith("~")
        and not PureWindowsPath(reference).anchor
        and not re.match(r"^[A-Za-z][A-Za-z0-9+.-]*:", reference)
    )


def execution_evidence(path: Path, data: dict, body: str) -> bool:
    refs = data.get("evidence", [])
    if string_list(refs):
        for reference in refs:
            if not relative_artifact(reference):
                continue
            try:
                artifact = (path.parent / reference).resolve()
                if artifact.is_file() and artifact.stat().st_size > 0:
                    return True
            except (OSError, ValueError):
                continue
    section = re.search(r"^##\s+Execution\s*(?:&|and)\s*results\s*\n(.*?)(?=^##\s|\Z)", body, re.I | re.M | re.S)
    if not section:
        return False
    blocks = re.findall(r"^(`{3,}|~{3,})[^\n]*\n(.*?)^\1\s*$", section[1], re.M | re.S)
    return any(len(content.strip().splitlines()) >= 2 and not re.search(r"\b(TODO|TBD|placeholder)\b", content, re.I) for _, content in blocks)


def validate_data(path: Path, data: dict, body: str) -> list[str]:
    errors = [f"missing key `{key}`" for key in sorted(REQUIRED - data.keys())]
    if errors:
        return errors
    for key in ("id", "title", "next_action"):
        if not is_text(data[key]):
            errors.append(f"`{key}` must be a nonempty string")
    if data["id"] != path.stem:
        errors.append(f"id `{data['id']}` != filename `{path.stem}`")
    for key, allowed in (("scope", SCOPES), ("status", STATUSES), ("verdict", VERDICTS)):
        if not isinstance(data[key], (str, type(None))) or data[key] not in allowed:
            errors.append(f"invalid `{key}`: {data[key]!r}")
    for key in ("build", "environment", "design", "owner", "branch"):
        if data.get(key) is not None and not is_text(data[key]):
            errors.append(f"`{key}` must be a nonempty string or null")
    if "env_role" in data and (not isinstance(data["env_role"], str) or data["env_role"] not in ENV_ROLES):
        errors.append("`env_role` must be dev, test, staging, production or unknown")
    for key in ("source_refs", "blockers", "evidence"):
        if key in data and not string_list(data[key]):
            errors.append(f"`{key}` must be a list of nonempty strings")
    if string_list(data.get("evidence")) and any(not relative_artifact(ref) for ref in data["evidence"]):
        errors.append("`evidence` entries must be local paths relative to the ticket")
    if data["status"] == "done" and data["verdict"] is None:
        errors.append("status done but verdict null")
    if data["verdict"] is not None and data["status"] != "done":
        errors.append(f"verdict set but status is `{data['status']}`")
    if data["status"] == "blocked" and not data["blockers"]:
        errors.append("blocked without a reason in `blockers`")
    dates = {}
    for key in ("started", "updated"):
        try:
            if not isinstance(data[key], str) or not re.fullmatch(r"\d{4}-\d{2}-\d{2}", data[key]):
                raise ValueError()
            dates[key] = date.fromisoformat(data[key])
        except ValueError:
            errors.append(f"`{key}` is not an ISO date: {data[key]!r}")
    if len(dates) == 2 and dates["updated"] < dates["started"]:
        errors.append("`updated` must not precede `started`")
    action = data["next_action"]
    if isinstance(action, str) and (len(action.strip()) < 12 or VAGUE.match(action.strip())):
        errors.append(f"next_action too vague: {action!r}")
    tracker = data["tracker"]
    if tracker is not None:
        parsed = urlparse(tracker) if isinstance(tracker, str) else None
        if parsed is None or parsed.scheme not in {"http", "https"} or not parsed.netloc:
            errors.append("tracker must be an http(s) URL or null")
    if data["status"] == "done" and data["verdict"] == "pass" and not execution_evidence(path, data, body):
        errors.append("verdict pass requires execution output under `## Execution & results` or a nonempty local evidence artifact")
    return errors


def load_ticket(path: Path) -> dict:
    data, body = parse_ticket(path.read_text(encoding="utf-8"))
    errors = validate_data(path, data, body)
    if errors:
        raise ValueError("; ".join(errors))
    return data


def check(path: Path) -> list[str]:
    try:
        load_ticket(path)
        return []
    except (OSError, ValueError) as exc:
        return [f"{path}: {exc}"]


def ticket_files(directory: Path = TICKETS) -> list[Path]:
    return sorted(path for path in directory.glob("*.md") if not path.name.startswith("_") and path.name != "INDEX.md")


def main(argv: list[str]) -> int:
    files = [Path(argument) for argument in argv] or ticket_files()
    errors = [error for path in files for error in check(path)]
    for error in errors:
        print(error)
    print(f"{len(files)} ticket(s) checked, {len(errors)} violation(s)")
    return int(bool(errors))


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
#!/usr/bin/env python3
"""Generate tickets/INDEX.md from validated frontmatter; --check detects drift."""
from __future__ import annotations

import html
import sys
from pathlib import Path
from urllib.parse import quote

sys.path.insert(0, str(Path(__file__).resolve().parent))
from validate import TICKETS, load_ticket, ticket_files  # noqa: E402

INDEX = TICKETS / "INDEX.md"
HEADER = (
    "# Tickets\n\n"
    "Generated by `tools/tickets/index.py` — do not edit by hand. One row per\n"
    "ticket file; the frontmatter is the source.\n\n"
    "| ID | Title | Scope | Status | Verdict | Updated | Next action |\n"
    "|---|---|---|---|---|---|---|\n"
)


def cell(value) -> str:
    text = "null" if value is None else str(value)
    return html.escape(text, quote=False).replace("\\", "\\\\").replace("|", "\\|").replace("\r\n", "\n").replace("\r", "\n").replace("\n", "<br>")


def render(directory: Path = TICKETS) -> str:
    tickets = []
    for path in ticket_files(directory):
        try:
            tickets.append((path, load_ticket(path)))
        except (OSError, ValueError) as exc:
            raise ValueError(f"{path}: {exc}") from exc
    tickets.sort(key=lambda item: item[1]["updated"], reverse=True)
    rows = []
    for path, data in tickets:
        label = cell(data["id"]).replace("[", "\\[").replace("]", "\\]")
        values = [f"[{label}]({quote(path.name)})"]
        values += [cell(data[key]) for key in ("title", "scope", "status", "verdict", "updated", "next_action")]
        rows.append("| " + " | ".join(values) + " |")
    return HEADER + "\n".join(rows) + ("\n" if rows else "")


def main(argv: list[str]) -> int:
    if argv not in ([], ["--check"]):
        print("usage: index.py [--check]", file=sys.stderr)
        return 2
    try:
        content = render()
        if "--check" in argv:
            current = INDEX.read_text(encoding="utf-8") if INDEX.exists() else ""
            if current != content:
                print("tickets/INDEX.md is stale — run python3 tools/tickets/index.py")
                return 1
            print("tickets/INDEX.md is current")
            return 0
        INDEX.write_text(content, encoding="utf-8")
    except (OSError, ValueError) as exc:
        print(f"Cannot generate ticket index: {exc}", file=sys.stderr)
        return 1
    print(f"wrote {INDEX.name}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
